  attempt: number;
  size: TaskSize;
  /** Name of the tier in tally.yaml that ran this attempt. */
  tier: string;
  model: string;
  harness: string;
  /** AO session id or direct runner's native harness session UUID; null for simulated attempts. */
  sessionId: string | null;
  /** Direct-runner environment setup, before the agent and its spend ceiling start. */
  setupDurationMs?: number;
  /** Native Entire/Codex session id, separate from the AO worker session. */
  entireSessionId?: string | null;
  branch: string | null;
  /** Effective comparison base at attempt start, including an inherited failed branch. */
  baseCommit?: string | null;
  tokens: TokenUsage;
  estimatedCostNanos: number;
  costSource: CostSource;
  /** Snapshot of the configured rates used for this attempt, not a retrospective repricing. */
  price?: TierPrice;
  /** Source, verification status and limitations of the cost estimate. */
  priceNote?: string;
  /** Spend ceiling that applied to this attempt. */
  ceilingNanos: number;
  result: AttemptResult;
  /** Short explanation of the result, e.g. "2 tests failing" or "ceiling crossed". */
  resultReason: string | null;
  /** Ended-attempt diagnosis; ledger fallback is explicit when the trace adds no evidence. */
  failureAssessment?: FailureAssessment;
  scopeWarnings?: string[];
  /** Refused worker tool calls; warnings unless the worker errored or made no commit. */
  permissionWarnings?: string[];
  /** Commit made by Tally for uncommitted direct-worker edits before verification. */
  tallyCommit?: string;
  /** attemptId of the attempt this one took over from, if it is an escalation. */
  escalatedFrom: string | null;
  handoff: Handoff;
  /** Exact context included in the worker prompt; null for an initial attempt. */
  handoffText?: string | null;
  prUrl: string | null;
  /** Neatlogs trace id for the routing or escalation decision that created this attempt. */
  traceId: string | null;
  traceUrl: string | null;
  /** Verified worker-session trace, distinct from the CFO decision trace. */
  workerTraceId?: string | null;
  workerTraceUrl?: string | null;
