  impact?: TaskImpact;
  changedFiles?: string[];
  status: TaskStatus;
  /** Why a task is failed or skipped, e.g. "not started: no budget". */
  statusReason: string | null;
  attempts: number;
  /** Tier of the latest attempt. */
  tier: string | null;
  model: string | null;
  spentNanos: number;
  escalated: boolean;
  prUrl: string | null;
}

export interface RunState {
  schemaVersion: 1;
  runId: string;
  mode: RunMode;
  repeat?: number;
  /** True when workers were simulated and nothing was spent. */
  dryRun: boolean;
  status: RunStatus;
  /** The repository the run worked on, as written in tally.yaml. */
  repo: string;
  backlog?: { source: 'github-issues' | 'file'; issueLabel?: string; file?: string };
  /** Commit every task branched from. */
  baseCommit: string | null;
  startedAt: string;
  updatedAt: string;
  endedAt: string | null;
  budget: {
    source: BudgetSource;
    monthly?: { source: BudgetSource; limitNanos: number; spentBeforeRunNanos: number };
    /** Origin of this run's effective limit, distinct from spend accounting. */
    limitSource?: BudgetSource | 'cli';
    systemOfRecord?: 'ledger' | 'cfoai';
    cfoai?: { pageUrl?: string; tableUrl?: string };
    limitNanos: number;
    /** Always the sum of estimatedCostNanos over this run's ledger rows. */
    spentNanos: number;
  };
  tasks: TaskState[];
  integrations: Record<IntegrationName, IntegrationState>;
}

