      lines.push({ product: harness === 'claude-code' ? 'Claude Code' : 'Codex', status: !status.installed ? 'missing' : status.signedIn ? 'connected' : 'broken', detail: status.detail, fix: status.installed && status.signedIn ? null : status.fix });
    }
