export type ParsedCli =
  | { kind: 'command'; command: Command; options: CliOptions }
  | { kind: 'help' }
  | { kind: 'version' }
  | { kind: 'error'; message: string };

export interface CliIO {
  stdout: (line: string) => void;
  stderr: (line: string) => void;
}

function printDoctorLine(line: DoctorLine, io: CliIO, style = createTerminalStyle()): void {
  for (const output of formatDoctorLine(line, style)) io.stdout(output);
}

function splitPlanClauses(value: string): string[] {
  const clauses: string[] = [];
  let part = '';
  let parentheses = 0;
  for (const character of value) {
    if (character === '(') parentheses += 1;
    if (character === ')') parentheses = Math.max(0, parentheses - 1);
    if (character === ';') {
      if (parentheses > 0) part += ',';
      else {
        if (part.trim()) clauses.push(part.trim());
        part = '';
      }
    } else part += character;
  }
  if (part.trim()) clauses.push(part.trim());
  return clauses;
}

function printPlanText(label: string, value: string, io: CliIO): void {
  const clauses = splitPlanClauses(value);
  if (!clauses.length) return;
  io.stdout(`  ${label}:`);
  for (const clause of clauses) {
    const prefix = '    - ';
    const continuation = ' '.repeat(prefix.length);
    const words = clause.split(/\s+/);
    let line = prefix;
    for (const word of words) {
      if (line.length > prefix.length && line.length + word.length + 1 > 88) {
        io.stdout(line);
        line = `${continuation}${word}`;
      } else {
        line += line.length === prefix.length ? word : ` ${word}`;
      }
    }
    io.stdout(line);
  }
}

